def _wrap(js: str) -> str:
    return CSS.replace('</style>', CSS_PLUS + '</style>') + '<section class="okm"><div id="okm-root"><div class="w"><p style="color:var(--m)">Yükleniyor…</p></div></div></section><script>' + js + '</script>'


def shop_page() -> str:
    return _wrap(SHOP_JS)


def account_page(shop: bool = True) -> str:
    return _wrap(ACC_JS.replace('__SHOP__', 'true' if shop else 'false'))
